result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/game.ts", "content": "/**
 * Idle-game balance simulation.
 *
 * Economy:
 *   - 5 generator tiers, i = 0..4
 *   - Base cost of tier i:        10 * 8^i
 *   - Base production of tier i:  1 * 3^i gold/tick
 *   - Cost escalation:            each unit owned multiplies that tier's
 *                                 cost by COST_GROWTH (standard idle-game
 *                                 mechanic; without it the cheapest-payback
 *                                 policy would always be tier 0, because
 *                                 static payback 10*(8/3)^i increases with
 *                                 tier, and higher tiers could never be
 *                                 purchased).
 *
 * Policy: every tick, first collect production from all owned generators,
 * then (if any purchase is affordable) buy the affordable purchase with the
 * smallest payback time (cost / marginal production gained). One purchase
 * per tick. Fully deterministic — no randomness, no wall-clock dependence.
 */

export const TICKS = 50_000;
export const TIER_COUNT = 5;

export const baseCost = (tier: number): number => 10 * 8 ** tier;
export const baseProd = (tier: number): number => 1 * 3 ** tier;
export const COST_GROWTH = 1.15;

export interface Purchase {
  tick: number;
  tier: number;
}

export interface SimSummary {
  ticks: number;
  /** Chronological purchase log. */
  purchases: Purchase[];
  /** First tick on which each tier was purchased (-1 if never). */
  firstPurchaseTick: number[];
  /** Units of each tier owned at end of run. */
  finalCounts: number[];
  /** Gold per tick at end of run. */
  finalGoldPerTick: number;
  /** Total gold accumulated over the whole run (net of spending). */
  finalGoldBalance: number;
  /** FNV-1a (32-bit) hash over the serialized purchase log + run length. */
  logHash: string;
}

/** Current price of the next unit of `tier`, given units already owned. */
export function currentCost(tier: number, owned: number): number {
  return baseCost(tier) * COST_GROWTH ** owned;
}

/** Payback time in ticks for the next unit of `tier`. */
function paybackTicks(tier: number, owned: number): number {
  return currentCost(tier, owned) / baseProd(tier);
}

/** FNV-1a, 32-bit, returned as zero-padded hex. Deterministic across runs/platforms. */
export function hashPurchases(purchases: Purchase[], ticks: number): string {
  // Seed mixes in the horizon so logs of different lengths can't collide trivially.
  let h = 0x811c9dc5 ^ (ticks & 0xffffffff);
  const mix = (byte: number) => {
    h ^= byte & 0xff;
    h = Math.imul(h, 0x01000193) >>> 0;
  };
  for (const p of purchases) {
    let t = p.tick;
    do {
      mix(48 + (t % 10));
      t = Math.floor(t / 10);
    } while (t > 0);
    mix(0x3a); // ':'
    mix(p.tier);
    mix(0x3b); // ';'
  }
  return h.toString(16).padStart(8, "0");
}

/** Run the simulation headlessly for `ticks` ticks. */
export function runSim(ticks: number = TICKS): SimSummary {
  const counts: number[] = new Array(TIER_COUNT).fill(0);
  const firstPurchaseTick: number[] = new Array(TIER_COUNT).fill(-1);
  const purchases: Purchase[] = [];

  let gold = 0;
  let goldPerTick = 0;

  for (let tick = 0; tick < ticks; tick++) {
    // 1) Collect production for this tick.
    gold += goldPerTick;

    // 2) Buy the affordable purchase with the smallest payback time.
    let bestTier = -1;
    let bestPayback = Infinity;
    for (let tier = 0; tier < TIER_COUNT; tier++) {
      const cost = currentCost(tier, counts[tier]!);
      if (gold < cost) continue;
      const pb = paybackTicks(tier, counts[tier]!);
      if (pb < bestPayback) {
        bestPayback = pb;
        bestTier = tier;
      }
    }
    if (bestTier >= 0) {
      gold -= currentCost(bestTier, counts[bestTier]!);
      goldPerTick += baseProd(bestTier);
      counts[bestTier]! += 1;
      if (firstPurchaseTick[bestTier] === -1) firstPurchaseTick[bestTier] = tick;
      purchases.push({ tick, tier: bestTier });
    }
  }

  return {
    ticks,
    purchases,
    firstPurchaseTick,
    finalCounts: counts,
    finalGoldPerTick: goldPerTick,
    finalGoldBalance: gold,
    logHash: hashPurchases(purchases, ticks),
  };
}
"})
