result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/report.ts", "content": "import { writeFileSync } from "node:fs";
import {
  runSim,
  TICKS,
  TIER_COUNT,
  baseCost,
  baseProd,
  COST_GROWTH,
  currentCost,
} from "./game.js";

const sim = runSim(TICKS);

const rows = [];
for (let tier = 0; tier < TIER_COUNT; tier++) {
  const first = sim.firstPurchaseTick[tier]!;
  const count = sim.finalCounts[tier]!;
  const contribution = count * baseProd(tier);
  const share = sim.finalGoldPerTick > 0 ? (100 * contribution) / sim.finalGoldPerTick : 0;
  rows.push(
    `| ${tier} | ${baseCost(tier)} | ${baseProd(tier)} | ` +
      `${first < 0 ? "never" : first.toLocaleString("en-US")} | ${count.toLocaleString("en-US")} | ` +
      `${contribution.toLocaleString("en-US")} | ${share.toFixed(2)}% |`,
  );
}

const md = `# Idle-Game Balance Report

## Model

- Tiers: **${TIER_COUNT}** (i = 0..${TIER_COUNT - 1})
- Base cost of tier i: \`10 * 8^i\`
- Base production of tier i: \`1 * 3^i\` gold/tick
- Cost escalation: each unit owned multiplies that tier's next cost by
  **×${COST_GROWTH}** (standard idle-game mechanic; without escalation the
  cheapest-payback policy degenerates to buying tier 0 forever, since static
  payback \\(10*(8/3)^i\\) strictly increases with tier).
- Policy: each tick, collect production, then buy the **affordable** purchase
  with the smallest payback time (\`cost / marginal production\`). One purchase per tick.
- Horizon: **${TICKS.toLocaleString("en-US")}** ticks, fully deterministic.

## Results

| Tier | Base cost | Base prod | First purchase tick | Final count | Prod contribution (g/t) | Share of final g/t |
|------|-----------|-----------|--------------------:|------------:|------------------------:|-------------------:|
${rows.join("\n")}

## Summary

| Metric | Value |
|--------|------:|
| Final gold per tick | ${sim.finalGoldPerTick.toLocaleString("en-US")} |
| Total purchases | ${sim.purchases.length.toLocaleString("en-US")} |
| Final gold balance | ${Math.floor(sim.finalGoldBalance).toLocaleString("en-US")} |
| Purchase-log hash (FNV-1a 32-bit) | \`${sim.logHash}\` |

_Generated by \`npm run report\`._
`;

writeFileSync("report.md", md);
console.log(`Wrote report.md (${sim.purchases.length.toLocaleString("en-US")} purchases, hash ${sim.logHash})`);
"})
