result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/idle.test.ts", "content": "import { describe, expect, it } from "vitest";
import {
  runSim,
  hashPurchases,
  TICKS,
  TIER_COUNT,
  baseProd,
  type Purchase,
} from "../src/game.js";

/** Gold-per-tick after each purchase, in chronological order. */
function goldPerTickSeries(purchases: Purchase[]): number[] {
  const series: number[] = [];
  let gpt = 0;
  for (const p of purchases) {
    gpt += baseProd(p.tier);
    series.push(gpt);
  }
  return series;
}

describe("idle-game balance sim", () => {
  const run1 = runSim(TICKS);

  it("gold-per-tick is non-decreasing over time", () => {
    const series = goldPerTickSeries(run1.purchases);
    // Gold-per-tick only changes at purchases; every purchase must not lower it.
    for (let i = 1; i < series.length; i++) {
      expect(series[i]!).toBeGreaterThanOrEqual(series[i - 1]!);
    }
    expect(series.length).toBeGreaterThan(0);
  });

  it("every tier gets purchased at least once", () => {
    for (let tier = 0; tier < TIER_COUNT; tier++) {
      expect(run1.firstPurchaseTick[tier], `tier ${tier} never purchased`).toBeGreaterThanOrEqual(0);
      expect(run1.finalCounts[tier]).toBeGreaterThanOrEqual(1);
    }
  });

  it("time-to-first-purchase per tier is strictly increasing with tier", () => {
    for (let tier = 1; tier < TIER_COUNT; tier++) {
      const prev = run1.firstPurchaseTick[tier - 1]!;
      const cur = run1.firstPurchaseTick[tier]!;
      expect(cur, `tier ${tier} first bought at ${cur}, not after tier ${tier - 1} at ${prev}`).toBeGreaterThan(prev);
    }
  });

  it("the run is deterministic (purchase-log hash is stable)", () => {
    const run2 = runSim(TICKS);
    expect(run2.logHash).toBe(run1.logHash);
    expect(run2.purchases).toEqual(run1.purchases);
    expect(run2.finalCounts).toEqual(run1.finalCounts);
    expect(hashPurchases([], TICKS)).toMatch(/^[0-9a-f]{8}$/);
  });

  it("respects the purchase policy (cheapest affordable payback, one per tick)", () => {
    // Replay the log and verify each entry was the best affordable move.
    const counts = new Array<number>(TIER_COUNT).fill(0);
    let gold = 0;
    let gpt = 0;
    const costOf = (t: number) => 10 * 8 ** t * 1.15 ** counts[t]!;
    let cursor = 0;
    for (let tick = 0; tick < TICKS; tick++) {
      gold += gpt;
      while (cursor < run1.purchases.length && run1.purchases[cursor]!.tick === tick) {
        const tier = run1.purchases[cursor]!.tier;
        // must be affordable
        expect(gold).toBeGreaterThanOrEqual(costOf(tier));
        // must have minimal payback among affordable tiers (strict < keeps earliest on ties)
        for (let other = 0; other < TIER_COUNT; other++) {
          if (gold >= costOf(other)) {
            expect(costOf(tier) / baseProd(tier)).toBeLessThanOrEqual(costOf(other) / baseProd(other));
          }
        }
        gold -= costOf(tier);
        counts[tier]! += 1;
        gpt += baseProd(tier);
        cursor++;
      }
    }
    expect(cursor).toBe(run1.purchases.length);
    expect(counts).toEqual(run1.finalCounts);
  });
});
"})
